### Python

```python
import sys

MOD = 10**9 + 7

# 计算单组测试数据的答案
def count_ways(n, k, a):
    # pre0[i] 表示前 i 个位置中，已知为 0 的数量
    pre0 = [0] * (n + 1)
    for i in range(1, n + 1):
        pre0[i] = pre0[i - 1] + (1 if a[i - 1] == 0 else 0)

    # dp[i] 表示前 i 个位置的合法填充方案数
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        # 情况 1：第 i 个位置填 1
        if a[i - 1] != 0:
            dp[i] = (dp[i] + dp[i - 1]) % MOD

        # 情况 2：第 i 个位置填 0
        if a[i - 1] != 1:
            s = max(1, i - k + 1)

            # 判断区间 [s, i - 1] 中是否存在已知的 0
            known_zero_cnt = pre0[i - 1] - pre0[s - 1]
            if known_zero_cnt == 0:
                dp[i] = (dp[i] + dp[s - 1]) % MOD

    return dp[n]


def main():
    input = sys.stdin.readline
    T = int(input().strip())
    ans = []

    for _ in range(T):
        n, k = map(int, input().split())
        a = list(map(int, input().split()))
        ans.append(str(count_ways(n, k, a)))

    print("\n".join(ans))


if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1000000007L;

    // 计算单组测试数据的答案
    static long countWays(int n, int k, int[] a) {
        // pre0[i] 表示前 i 个位置中，已知为 0 的数量
        int[] pre0 = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            pre0[i] = pre0[i - 1] + (a[i] == 0 ? 1 : 0);
        }

        // dp[i] 表示前 i 个位置的合法填充方案数
        long[] dp = new long[n + 1];
        dp[0] = 1;

        for (int i = 1; i <= n; i++) {
            // 情况 1：第 i 个位置填 1
            if (a[i] != 0) {
                dp[i] = (dp[i] + dp[i - 1]) % MOD;
            }

            // 情况 2：第 i 个位置填 0
            if (a[i] != 1) {
                int s = Math.max(1, i - k + 1);

                // 判断区间 [s, i - 1] 中是否存在已知的 0
                int knownZeroCnt = pre0[i - 1] - pre0[s - 1];
                if (knownZeroCnt == 0) {
                    dp[i] = (dp[i] + dp[s - 1]) % MOD;
                }
            }
        }

        return dp[n];
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();

        int T = Integer.parseInt(br.readLine().trim());

        while (T-- > 0) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());

            int[] a = new int[n + 1];
            st = new StringTokenizer(br.readLine());
            for (int i = 1; i <= n; i++) {
                a[i] = Integer.parseInt(st.nextToken());
            }

            out.append(countWays(n, k, a)).append('\n');
        }

        System.out.print(out);
    }
}
